import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import response from '../train_details.json'
import Station from '../components/Station';

function TrainDetails() {
  const { train_number } = useParams();
  const [route, setRoute] = useState([]);

  useEffect(() => {
    const fetchTrainRoute = async () => {
      const options = {
        method: 'GET',
        url: 'https://irctc1.p.rapidapi.com/api/v1/liveTrainStatus',
        params: {
          trainNo: train_number
        },
        headers: {
          'x-rapidapi-key': '620b4221e7mshcda6c85c7c7d26ap16949ajsn7449facb1aa5',
          'x-rapidapi-host': 'irctc1.p.rapidapi.com'
        }
      };
      
      try {
        const response = await axios.request(options);
        console.log(response.data);
        setRoute(response.data)
      } catch (error) {
        console.error(error);
      }
    };

    fetchTrainRoute();
  }, []);

  console.log(route)
  return (
    <div style={{backgroundColor: '#97AEAF', height: '100%', padding: 20}}>
      {route && <h1 style={{padding: '3%', textAlign: 'center'}}>{response["train_name"]}</h1>}
      {route && <h4 style={{paddingLeft: '10%', textAlign: 'left'}}>Recent Update: {response["message"]}</h4>}
      {route.map(station_info => (
        <Station key={station_info.id} station_info={station_info} />
      ))}
    </div>
  );
}

export default TrainDetails;
